using System;using System.IO;using UnityEditor;using UnityEngine;using YardSurvivalPrototype;
[InitializeOnLoad]public static class FeatureChecksReview {static FeatureChecksReview(){EditorApplication.update+=Poll;}static void Poll(){const string file="Assets/LastDeparturePrototype/FeatureChecks.request";if(!File.Exists(file)||EditorApplication.isCompiling||EditorApplication.isUpdating||!EditorApplication.isPlaying)return;File.Delete(file);try{var game=UnityEngine.Object.FindAnyObjectByType<YardSurvival>();string footsteps=game.RunFootstepTimingChecks();File.WriteAllText("Assets/LastDeparturePrototype/FootstepTimingChecks.txt",footsteps);File.WriteAllText("Assets/LastDeparturePrototype/FeatureChecks.txt",game.RunFeatureChecks()+"\n"+game.RunPeerInventoryChecks());}catch(Exception e){File.WriteAllText("Assets/LastDeparturePrototype/FeatureChecks.txt","FAIL "+e);}}}
